<?php require __DIR__.'/includes/config.php';require_login();if($_SESSION['user']['role']!=='PROVIDER'){header('Location: admin.php');exit;}$q=$pdo->prepare('SELECT * FROM installations WHERE provider_id=? ORDER BY city,store_name');$q->execute([$_SESSION['user']['id']]);$stores=$q->fetchAll();$pageTitle='Mes magasins';require __DIR__.'/includes/header.php';?><div class="flex flex-wrap justify-between items-end gap-3 mb-6"><div><div class="text-xs uppercase tracking-widest brand font-bold">Espace prestataire</div><h1 class="text-3xl font-extrabold mt-2">Mes magasins</h1><p class="text-stone-500 mt-1">Vos missions et relevés terrain.</p></div><div class="card px-4 py-3"><span class="text-stone-500 text-sm">Missions affectées</span><div class="text-2xl font-extrabold brand"><?=count($stores)?></div></div></div><?php if(!$stores):?><div class="card p-6 text-stone-500">Aucun magasin n'est affecté à ce compte.</div><?php endif;?><div class="grid sm:grid-cols-2 xl:grid-cols-3 gap-4"><?php foreach($stores as $s):?><a class="card p-5 hover:shadow-md transition" href="store.php?id=<?=(int)$s['id']?>"><div class="flex justify-between gap-2"><span class="text-xs uppercase tracking-wider gold font-bold"><?=e($s['banner'])?></span><span class="text-xs rounded-full bg-stone-100 px-2 py-1"><?=e(status_label($s['status']))?></span></div><h2 class="text-lg font-bold mt-3"><?=e($s['store_name'])?></h2><p class="text-sm text-stone-500 mt-1"><?=e($s['city'])?></p><div class="mt-5 text-sm font-semibold brand">Ouvrir la mission →</div></a><?php endforeach;?></div><?php require __DIR__.'/includes/footer.php'; ?>